// Command wordfreq reads standard input and prints the 10 most frequent
// ASCII words.
//
// A word is a maximal run of ASCII letters, folded to lowercase. Output is
// "<count> <word>" per line, ordered by count descending, then word ascending
// (byte order), at most 10 lines.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const topN = 10

func main() {
	counts, err := countWords(os.Stdin)
	if err != nil {
		// Report the failure but still print what was read, as the
		// original implementation does.
		fmt.Fprintf(os.Stderr, "wordfreq: read error: %v\n", err)
	}

	w := bufio.NewWriter(os.Stdout)
	for _, e := range top(counts, topN) {
		fmt.Fprintf(w, "%d %s\n", e.count, e.word)
	}
	if err := w.Flush(); err != nil {
		os.Exit(1)
	}
}

// readChunk is the size of each read from the input.
const readChunk = 1 << 16

// countWords counts the lowercase-folded ASCII words in r. On a read error
// it returns the counts gathered so far along with the error.
func countWords(r io.Reader) (map[string]int, error) {
	counts := make(map[string]int, 1024)
	buf := make([]byte, readChunk)
	var carry []byte // word that may continue past the end of a chunk

	for {
		n, err := r.Read(buf)
		chunk := buf[:n]
		for i := 0; i < len(chunk); {
			if len(carry) > 0 {
				for i < len(chunk) && isLetter(chunk[i]) {
					carry = append(carry, chunk[i]|0x20)
					i++
				}
				if i < len(chunk) {
					counts[string(carry)]++
					carry = carry[:0]
				}
				continue
			}

			for i < len(chunk) && !isLetter(chunk[i]) {
				i++
			}
			start := i
			for i < len(chunk) && isLetter(chunk[i]) {
				chunk[i] |= 0x20
				i++
			}
			switch {
			case i == start:
				// Only separators remained in this chunk.
			case i < len(chunk):
				counts[string(chunk[start:i])]++
			default:
				carry = append(carry, chunk[start:i]...)
			}
		}

		if err == io.EOF {
			break
		}
		if err != nil {
			flush(counts, carry)
			return counts, err
		}
	}
	flush(counts, carry)
	return counts, nil
}

func flush(counts map[string]int, carry []byte) {
	if len(carry) > 0 {
		counts[string(carry)]++
	}
}

// isLetter reports whether c is an ASCII letter.
func isLetter(c byte) bool {
	return (c|0x20)-'a' < 26
}

package main

import (
	"reflect"
	"strings"
	"testing"
	"testing/iotest"
)

func run(t *testing.T, input string) []entry {
	t.Helper()
	counts, err := countWords(strings.NewReader(input))
	if err != nil {
		t.Fatal(err)
	}
	return top(counts, topN)
}

func TestExamples(t *testing.T) {
	tests := []struct {
		in   string
		want []entry
	}{
		{"The cat and the hat.", []entry{{"the", 2}, {"and", 1}, {"cat", 1}, {"hat", 1}}},
		{"don't stop_me 4now, now-NOW", []entry{{"now", 3}, {"don", 1}, {"me", 1}, {"stop", 1}, {"t", 1}}},
		{"", []entry{}},
		{"123 \xff\xc3( ...", []entry{}},
		{"caf\xc3\xa9 CAF", []entry{{"caf", 2}}},
	}
	for _, tt := range tests {
		got := run(t, tt.in)
		if len(got) == 0 && len(tt.want) == 0 {
			continue
		}
		if !reflect.DeepEqual(got, tt.want) {
			t.Errorf("%q: got %v, want %v", tt.in, got, tt.want)
		}
	}
}

func TestWordAcrossChunks(t *testing.T) {
	long := strings.Repeat("a", readChunk*3+7)
	input := strings.Repeat("x", readChunk-2) + "yz " + long + " " + long
	counts, err := countWords(iotest.OneByteReader(strings.NewReader(input)))
	if err != nil {
		t.Fatal(err)
	}
	if counts[long] != 2 || counts[strings.Repeat("x", readChunk-2)+"yz"] != 1 || len(counts) != 2 {
		t.Errorf("unexpected counts: %d words", len(counts))
	}
}

func TestTopLimit(t *testing.T) {
	got := run(t, "zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha")
	want := []entry{{"alpha", 2}, {"beta", 1}, {"eta", 1}, {"iota", 1}, {"kappa", 1},
		{"lambda", 1}, {"mu", 1}, {"nu", 1}, {"omicron", 1}, {"pi", 1}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

package main

// entry is a word and its number of occurrences.
type entry struct {
	word  string
	count int
}

// ranksBefore reports whether a ranks before b: higher count first, then
// lexicographically smaller word.
func ranksBefore(a, b entry) bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return a.word < b.word
}

// top returns up to n entries from counts, best-ranked first.
func top(counts map[string]int, n int) []entry {
	if n <= 0 {
		return nil
	}
	out := make([]entry, 0, n)
	for word, count := range counts {
		e := entry{word, count}
		if len(out) == n {
			if !ranksBefore(e, out[n-1]) {
				continue
			}
			out = out[:n-1]
		}
		// Insertion into the small sorted slice.
		out = append(out, e)
		pos := len(out) - 1
		for pos > 0 && ranksBefore(e, out[pos-1]) {
			out[pos] = out[pos-1]
			pos--
		}
		out[pos] = e
	}
	return out
}
